mapper.select:
SELECT id, account_email AS accountEmail, folder, message_uid AS messageUid, subject, from_address AS fromAddress, to_address AS toAddress, cc_address AS ccAddress, send_date AS sendDate, has_attachment AS hasAttachment, eml_path AS emlPath, body_preview AS bodyPreview, archived_at AS archivedAt FROM email_archive
AND account_email = #{accountEmail} AND from_address LIKE '%' || #{fromAddress} || '%' AND subject LIKE '%' || #{subject} || '%' AND send_date >= #{startDate} AND send_date <= #{endDate}
ORDER BY send_date DESC LIMIT 100
